      "login": "andrewtoth",
      "stance": "objection",
      "note": "Concept ACKed, but raised concerns about SetDirty clearing freshness, log message wording, and removed comments, all resolved by author updates"
    },
    {
      "login": "optout21",
      "stance": "support",
      "note": "ACKed and reACKed citing code maintainability benefits and elimination of invalid cache states"
    },
    {
      "login": "ptrinh",
      "stance": "support",
      "note": "tested coins fuzz targets and unit suites on the branch without issues and confirmed invariant consistency"
    }
  ],
  "claims": [
    {
      "id": "rc:3105667838",
      "kind": "correctness",
      "harm": "SetDirty could unexpectedly clear freshness on an already fresh entry",
      "quote": "Why do we want to set a fresh entry to not-fresh? If an entry is fresh, it should stay fresh until cleaned or erased as before.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3107400554"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3107400554",
      "settled_by_quote": "Added `Assume(!pair.second.m_fresh || fresh)` so the API can't silently clear FRESH, thanks"
    },
    {
      "id": "rc:3105647133",
      "kind": "interface",
      "harm": "removing 'changed' from the log message conflates committing deleted outputs with committing only new outputs",
      "quote": "The `changed` adjective could be left here. Existing transaction outputs that are deleted are `changed`. The log now can be conflated with committing only new transactions outputs.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3107400760"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3107400760",
      "settled_by_quote": "Added `changed` back"
    },
    {
      "id": "rc:3105640231",
      "kind": "maintenance",
      "harm": "removing a relevant comment loses valuable context",
      "quote": "Why remove this comment? It's still relevant and provides valuable context.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3107401207"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3107401207",
      "settled_by_quote": "Restored above the new `SetDirty` call"
    }
  ],
  "support": [
    {
      "id": "r:4134896528",
      "verdict": "Concept ACK",
      "reason": "Thanks for picking this up.",
      "substantive": false
    },
    {
      "id": "r:4164135258",
      "verdict": "ACK",
      "reason": "Post-change the invalid states cannot be represented. This change is a code maintainability benefit, because any code change could potentially break the conventions. It also results in slightly simpler code.",
      "substantive": true
    },
    {
      "id": "c:4787121241",
      "verdict": "",
      "reason": "Tested the coins fuzz targets on this branch... No crashes, OOMs, sanitizer errors, or hits on the new BatchWrite() logic_error... read through the BatchWrite/SetDirty/IsDirty changes and the fresh-implies-dirty invariant looks internally consistent.",
      "substantive": true
    },
    {
      "id": "c:5566315263",
      "verdict": "ACK",
      "reason": "No issues. A net reduction in complexity around coins view flags",
      "substantive": true
    }
  ],
  "notes": "Initial record for PR 34864. Andrewtoth's concerns regarding SetDirty freshness clearing, log message wording, and comment removal were all resolved with pushed updates; optout21 and ptrinh provided substantive support."
}
